package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** Distinguish equivalence from neighbouring hundredths in either public operand order. */
public final class FractionDecimalComparison {
 private FractionDecimalComparison(){}
 public static final String ID="fractionDecimalCompare";
 public static final Set<Integer> DENOMINATORS=Set.of(2,4,5,10,100);
 public record Givens(int numerator,int denominator,int hundredths,boolean fractionLeft){}
 static String decimal(int h){return (h/100)+"."+String.format(Locale.ROOT,"%02d",h%100);}
 public static Givens read(Question q){if(q==null||!ID.equals(q.skillId)||q.prompt==null)return null;String prefix="분수와 소수를 비교하세요.\n";if(!q.prompt.startsWith(prefix))return null;String raw=q.prompt.substring(prefix.length());Matcher m=Pattern.compile("(\\d{1,3})/(\\d{1,3})  □  ([01]\\.\\d{2})").matcher(raw);boolean left=m.matches();if(!left){m=Pattern.compile("([01]\\.\\d{2})  □  (\\d{1,3})/(\\d{1,3})").matcher(raw);if(!m.matches())return null;}int n=Integer.parseInt(m.group(left?1:2)),d=Integer.parseInt(m.group(left?2:3)),h=new java.math.BigDecimal(m.group(left?3:1)).movePointRight(2).intValue();return DENOMINATORS.contains(d)&&n>=0&&n<=d&&h>=0&&h<=100?new Givens(n,d,h,left):null;}
 static String sign(Givens v){int cmp=Rational.of(v.numerator,v.denominator).compareTo(Rational.of(v.hundredths,100));if(!v.fractionLeft)cmp=-cmp;return cmp<0?"<":cmp>0?">":"=";}
 static Question make(int n,int d,int h,boolean left){String f=n+"/"+d,decimal=decimal(h);Question q=new Question(ID,"분수와 소수를 비교하세요.\n"+(left?f+"  □  "+decimal:decimal+"  □  "+f),"","");Givens v=read(q);if(v==null)throw new IllegalArgumentException("Selected fraction/decimal domain");q.answers=new String[]{sign(v)};q.kind="symbol";q.stepSupport=false;attach(q);return q.withInputs(n,d,h);}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){List<int[]> pool=new ArrayList<>();for(int d:limits.fractionDenominators())if(DENOMINATORS.contains(d))for(int n=0;n<=d;n++)for(int offset=-1;offset<=1;offset++){int h=100*n/d+offset;if(h>=0&&h<=100)for(int left=0;left<=1;left++)pool.add(new int[]{n,d,h,left});}return IndexedQuestionSupply.choose(pool.size(),i->{int[] v=pool.get(i);return make(v[0],v[1],v[2],v[3]==1);},random,limits,recent);}
 static Checker.Result check(Question q,List<String> answers){Givens v=read(q);if(v==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"문제 확인 필요");if(answers==null||answers.size()!=1||answers.get(0)==null||!Set.of("<","=",">").contains(answers.get(0)))return new Checker.Result(Checker.Status.INPUT_NEEDED,-1,"비교 기호 선택 필요");return answers.get(0).equals(sign(v))?new Checker.Result(Checker.Status.CORRECT,-1,"계산 확인 완료"):new Checker.Result(Checker.Status.WRONG_ANSWER,0,"이 답 확인");}
 public static void attach(Question q){Givens v=read(q);if(v==null)return;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="fraction-decimal-comparison-v1";h.step("주어진 분수의 분자를 쓰세요.","분수의 분자 n = ","",Integer.toString(v.numerator));h.step("주어진 분수의 분모를 쓰세요.","분수의 분모 d = ","",Integer.toString(v.denominator));h.step("분자를 분모로 나누어 소수로 쓰세요.","분수의 소수 값 v = n ÷ d = ","",decimal(100*v.numerator/v.denominator));h.frames.get(2).inputFormat="decimal";h.step("문제에 주어진 소수를 쓰세요.","주어진 소수 x = ","",decimal(v.hundredths));h.frames.get(3).inputFormat="decimal";h.choice("원래 왼쪽과 오른쪽 값을 비교해 기호를 고르세요.",Map.of("<","<","=","=",">",">"),sign(v));q.studyGuide=h;}
}
